import { HTTPResponse } from "../response.ts";

export interface StaticAssetMeta {
  type?: string;
  etag?: string;
  mtime?: number | string | Date;
  size?: number;
  encoding?: string;
}

export interface ServeStaticOptions {
  /**
   * This function should resolve asset meta.
   *
   * `size` is the number of bytes `getContents` returns (for strings, UTF-8
   * bytes, not characters). It drives `Content-Length` and `Range` requests.
   *
